import ast
import json
import os
import sys


def main(root):
    results = []
    for dirpath, dirnames, filenames in os.walk(os.path.join(root, "repo")):
        dirnames[:] = sorted(d for d in dirnames if d != "__pycache__")
        for fname in sorted(filenames):
            if not fname.endswith(".py"):
                continue
            path = os.path.join(dirpath, fname)
            rel = os.path.relpath(path, root).replace(os.sep, "/")
            try:
                with open(path, "r", encoding="utf-8") as fh:
                    source = fh.read()
                tree = ast.parse(source, filename=path)
            except SyntaxError as exc:
                print(f"SKIP (syntax error): {rel}: {exc}", file=sys.stderr)
                continue
            for node in ast.walk(tree):
                if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    lines = node.end_lineno - node.lineno + 1
                    if lines > 30:
                        results.append(
                            {"file": rel, "name": node.name, "lines": lines}
                        )
    results.sort(key=lambda r: (r["file"], r["name"], r["lines"]))
    with open(os.path.join(root, "audit.json"), "w", encoding="utf-8") as fh:
        json.dump(results, fh, indent=2)
        fh.write("\n")
    print(f"wrote {len(results)} entries")


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else ".")

